CH = string.ascii_lowercase
MASK = 0
V = len(CH) + 1
N = 5
STOI = {c: i + 1 for i, c in enumerate(CH)}
TRAIN_SET, FULL = set(WORDS), set(WORDS) | set(EVAL_WORDS)

class Net(nn.Module):
    def __init__(self, dim=256, heads=4, layers=6, ff=1024):
        super().__init__()
        self.tok = nn.Embedding(V, dim)
        self.pos = nn.Parameter(torch.zeros(1, N, dim))
        block = nn.TransformerEncoderLayer(dim, heads, ff, dropout=0.0,
                  activation="gelu", batch_first=True, norm_first=True)
        self.blocks = nn.TransformerEncoder(block, layers)
        self.norm = nn.LayerNorm(dim)
        self.head = nn.Linear(dim, V)

    def forward(self, x):
        h = self.tok(x) + self.pos
        return self.head(self.norm(self.blocks(h)))

@torch.no_grad()
def p_for(model, tokens):
    logits = model(tokens.unsqueeze(0))[0]
    logits[:, MASK] = float("-inf")
    return logits.softmax(-1)

def draw(p_row, T):
    if T <= 0.05:
        return int(p_row.argmax())
    q = p_row.pow(1.0 / T)
    q = q / q.sum()
    return int(torch.multinomial(q, 1))

def init_toks(pre=None):
    toks = torch.full((N,), MASK, dtype=torch.long, device=dev)
    for pos, ch_ in (pre or {}).items():
        toks[pos] = STOI[ch_]
    return toks

def word_of(toks):
    return "".join(CH[int(t) - 1] for t in toks)

# ---------- samplers: all return (tokens, passes, revisions) ----------

def s_ancestral(model, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        i = max(masked, key=lambda j: p[j].max().item())
        toks[i] = draw(p[i], T)
    return toks, passes, 0

def s_k2(model, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        ranked = sorted(masked, key=lambda j: p[j].max().item(), reverse=True)
        for i in ranked[:2]:
            if toks[i] == MASK:
                toks[i] = draw(p[i], T)
    return toks, passes, 0

def s_threshold(model, thr=0.9, T=1.0, pre=None):
    toks = init_toks(pre); passes = 0
    while (toks == MASK).any():
        p = p_for(model, toks); passes += 1
        masked = (toks == MASK).nonzero().squeeze(1).tolist()
        conf = {j: p[j].max().item() for j in masked}
        sure = [j for j in masked if conf[j] >= thr] or [max(conf, key=conf.get)]
        for j in sure:
            toks[j] = draw(p[j], T)
    return toks, passes, 0

def s_revision(model, T=0.7, tau=0.15, max_steps=24, max_rev=2, pre=None):
    toks = init_toks(pre); passes = 0; revs = [0] * N
    sacred = set((pre or {}).keys())
    for _ in range(max_steps):
        p = p_for(model, toks); passes += 1
        committed = [j for j in range(N) if toks[j] != MASK]
        weak = [j for j in committed
                if j not in sacred
                and p[j, int(toks[j])].item() < tau and revs[j] < max_rev]
        if weak:
            for j in weak:
                toks[j] = MASK; revs[j] += 1
            continue
        masked = [j for j in range(N) if toks[j] == MASK]
        if not masked:
            break
        i = max(masked, key=lambda j: p[j].max().item())
        toks[i] = draw(p[i], T)
    return toks, passes, sum(revs)

# ----------------------------------------------------------------------

def evaluate(model, fn, n=512, **kw):
    torch.manual_seed(0)
    outs, passes_tot, revs_tot = [], 0, 0
    for _ in range(n):
        toks, ps, rv = fn(model, **kw)
        outs.append(word_of(toks)); passes_tot += ps; revs_tot += rv
    return {"valid_train": round(sum(w in TRAIN_SET for w in outs) / n, 3),
            "valid_english": round(sum(w in FULL for w in outs) / n, 3),
            "unique": len(set(outs)),
            "passes_per_sample": round(passes_tot / n, 2),
            "revisions_per_sample": round(revs_tot / n, 2),
            "top5": Counter(outs).most_common(5)}

# ================= ARM A: frozen v2 weights, sampler study ============

urllib.request.urlretrieve(
    "https://huggingface.co/PastelRuntime/KB-Diffusion-ModelB/resolve/main/modelb_v2.pt",
    "modelb_v2.pt")
v2 = Net(layers=6).to(dev)
v2.load_state_dict(torch.load("modelb_v2.pt", map_location=dev, weights_only=True))
v2.eval()
print(f"v2 weights loaded from HF, params "
      f"{sum(p.numel() for p in v2.parameters())/1e6:.2f}M", flush=True)

SAMPLERS = {
    "ancestral_t1.0": (s_ancestral, {"T": 1.0}),
    "ancestral_t0.7": (s_ancestral, {"T": 0.7}),
    "ancestral_t0.5": (s_ancestral, {"T": 0.5}),
    "threshold_0.9":  (s_threshold, {"thr": 0.9, "T": 1.0}),
    "k2":             (s_k2, {}),
    "revision":       (s_revision, {}),
}
armA = {}
for name, (fn, kw) in SAMPLERS.items():
    armA[name] = evaluate(v2, fn, **kw)
    r = armA[name]
    print(f"A/{name:15s} english {r['valid_english']:5.1%}  unique {r['unique']:3d}/512"
          f"  passes {r['passes_per_sample']:5.2f}  revs {r['revisions_per_sample']:4.2f}"
          f"  top {r['top5'][:2]}", flush=True)

best_name = max(armA, key=lambda k: armA[k]["valid_english"])
print(f"best sampler on frozen v2: {best_name} "
      f"({armA[best_name]['valid_english']:.1%})", flush=True)

# ================= ARM B: v3 model, retrain ===========================

data = torch.tensor([[STOI[c] for c in w] for w in WORDS], device=dev)
v3 = Net(layers=8).to(dev)
print(f"v3 params {sum(p.numel() for p in v3.parameters())/1e6:.2f}M", flush=True)
opt = torch.optim.AdamW(v3.parameters(), lr=3e-4, weight_decay=0.01)
steps, bs = 12000, 1024
sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=steps, eta_min=3e-5)
for step in range(1, steps + 1):
    x0 = data[torch.randint(0, len(data), (bs,), device=dev)]
    t = torch.rand(bs, 1, device=dev).clamp(min=0.05)
    mask = torch.rand(bs, N, device=dev) < t
    mask[mask.sum(1) == 0, 0] = True
    xt = torch.where(mask, torch.full_like(x0, MASK), x0)
    logits = v3(xt)
    ce = F.cross_entropy(logits.view(-1, V), x0.view(-1),
                         reduction="none").view(bs, N)
    loss = ((ce * mask).sum(1) / t.squeeze(1)).mean() / N
    opt.zero_grad(); loss.backward(); opt.step(); sched.step()
    if step % 2000 == 0:
        with torch.no_grad():
            acc = ((logits.argmax(-1) == x0) & mask).float().sum() / mask.sum()
        print(f"v3 step {step:5d}  loss {loss.item():7.4f}  masked-acc {acc:6.1%}",
              flush=True)
v3.eval()

armB = {"meta": {"layers": 8, "steps": steps, "params":
         round(sum(p.numel() for p in v3.parameters())/1e6, 2)}}
for name in ["ancestral_t1.0", "threshold_0.9", "revision", best_name]:
    fn, kw = SAMPLERS[name]
    armB[name] = evaluate(v3, fn, **kw)
    r = armB[name]
    print(f"B/{name:15s} english {r['valid_english']:5.1%}  unique {r['unique']:3d}/512"
          f"  passes {r['passes_per_sample']:5.2f}  revs {r['revisions_per_sample']:4.2f}"
          f"  top {r['top5'][:2]}", flush=True)

# ================= prompting: fixed first letter on v3 ================

fn_best, kw_best = SAMPLERS[best_name]
torch.manual_seed(0)
prompt_outs = []
for L in CH:
    for _ in range(32):
        toks, _, _ = fn_best(v3, pre={0: L}, **kw_best)
        prompt_outs.append((L, word_of(toks)))
per_letter = {L: round(sum(w in FULL for l, w in prompt_outs if l == L) / 32, 3)
              for L in CH}
prompt_overall = round(sum(w in FULL for _, w in prompt_outs) / len(prompt_outs), 3)
print(f"prompted (fixed 1st letter, {best_name} on v3): "
      f"{prompt_overall:.1%} valid english overall", flush=True)
print(f"  easiest letters: {sorted(per_letter.items(), key=lambda kv: -kv[1])[:5]}",
      flush=True)
print(f"  hardest letters: {sorted(per_letter.items(), key=lambda kv: kv[1])[:5]}",
      flush=True)

# ================= conditional Bayes check on v3 ======================

def analytic_cond(prefix, pos):
    c = torch.zeros(V, device=dev)
    for w in WORDS:
        if w.startswith(prefix):
            c[STOI[w[pos]]] += 1
    return c / c.sum()

bayes = {}
for prefix in ["qu", "br", "st", "ch", "th", "ze"]:
    toks = init_toks({i: c for i, c in enumerate(prefix)})
    m = p_for(v3, toks)[len(prefix)]
    a = analytic_cond(prefix, len(prefix))
    tv = (0.5 * (m - a).abs().sum()).item()
    top_m = CH[int(m.argmax())]
    top_a = CH[int(a.argmax())]
    bayes[prefix] = {"tv": round(tv, 4), "model_top": top_m, "analytic_top": top_a}
    print(f"prefix '{prefix}': TV {tv:.4f}  model top '{top_m}' vs analytic '{top_a}'",
          flush=True)

uni = torch.zeros(N, V, device=dev)
for w in WORDS:
    for i, c in enumerate(w):
        uni[i, STOI[c]] += 1
uni /= uni.sum(1, keepdim=True)
with torch.no_grad():
    p0 = p_for(v3, init_toks())
tv0 = (0.5 * (p0 - uni).abs().sum(1)).mean().item()
print(f"v3 unigram TV: {tv0:.4f} (v2 was 0.0374)", flush=True)

# ======================================================================

results = {"armA_frozen_v2": armA, "best_sampler": best_name,
           "armB_v3": armB,
           "prompting_v3": {"overall": prompt_overall, "per_letter": per_letter,
                            "sampler": best_name, "n_per_letter": 32},
           "bayes_checks_v3": {"prefixes": bayes, "unigram_tv": round(tv0, 4)}}
json.dump(results, open("results.json", "w"), indent=2)
torch.save(v3.state_dict(), "modelb_v3.pt")
print("DONE", flush=True)
